"""Live Section dimensions on a joined complete Bundle member.

Semantic Sections keep their constant authored dimensions. Only explicitly
declared seams receive the same finite quintic taper as ordinary carriageways.
The joined curve retains one outgoing-span record per control. Neither spatial
proximity nor interpolation of integer IDs establishes Section ownership.
"""

FIELDS = {'width':'FLOAT', 'offset':'FLOAT', 'length':'FLOAT', 'prefix':'FLOAT'}
for _side in ('start','end'):
    for _suffix,_kind in (('id','INT'),('length','FLOAT'),('width','FLOAT'),('offset','FLOAT')):
        FIELDS[_side+'_'+_suffix] = _kind


def prepare(g, oriented):
    """Attach oriented per-Section dimensions and conservative derivative bounds."""
    index=g.node('GeometryNodeInputIndex','Member Section metadata index').outputs[0]
    reverse=g.boolean('NOT',g.named('st_chain_forward','BOOLEAN'))
    fields={n:(g.named('st_sweep_'+n,k),k) for n,k in (('width','FLOAT'),('offset','FLOAT'))}
    spline=g.node('GeometryNodeSplineLength','Actual unchanged Section arc length')
    fields['length']=(spline.outputs['Length'],'FLOAT')
    prefix=g.node('GeometryNodeAccumulateField','Exclusive Section arc-length prefixes')
    prefix.domain='CURVE';prefix.data_type='FLOAT';g.set(spline.outputs['Length'],prefix.inputs['Value'])
    fields['prefix']=(prefix.outputs['Trailing'],'FLOAT')
    for side in ('start','end'):
        other='end' if side=='start' else 'start'
        for suffix,kind in (('id','INT'),('length','FLOAT'),('width','FLOAT'),('offset','FLOAT')):
            a=g.named('st_sweep_'+side+'_transition_'+suffix,kind)
            b=g.named('st_sweep_'+other+'_transition_'+suffix,kind)
            if suffix=='offset':b=g.math('MULTIPLY',-1.,b)
            fields[side+'_'+suffix]=(g.switch(reverse,a,b,kind),kind)
    result=oriented
    for name,(value,kind) in fields.items():
        result=g.store(result,'st_span_'+name,g.sample(oriented,value,index,kind,'CURVE'),kind,'CURVE')
    value=lambda name,kind='FLOAT':g.named('st_span_'+name,kind)
    active=[];bounds=[];reach=g.math('ADD',g.math('ABSOLUTE',value('offset')),g.math('MULTIPLY',.5,value('width')))
    for side in ('start','end'):
        half=value(side+'_length')
        enabled=g.all(g.compare(value(side+'_id','INT'),0,'GREATER_EQUAL','INT'),g.compare(half,0.,'GREATER_THAN'))
        active.append(enabled)
        delta=g.math('ADD',g.math('ABSOLUTE',g.math('SUBTRACT',value(side+'_offset'),value('offset'))),
                   g.math('MULTIPLY',.5,g.math('ABSOLUTE',g.math('SUBTRACT',value(side+'_width'),value('width')))))
        first=g.math('DIVIDE',g.math('MULTIPLY',1.875,delta),g.math('MAXIMUM',half,1e-6))
        second=g.math('DIVIDE',g.math('MULTIPLY',5.773503,delta),g.math('MAXIMUM',g.math('MULTIPLY',half,half),1e-12))
        bounds.append((g.switch(enabled,0.,first),g.switch(enabled,0.,second)))
        joint_reach=g.math('ADD',g.math('ABSOLUTE',value(side+'_offset')),g.math('MULTIPLY',.5,value(side+'_width')))
        reach=g.math('MAXIMUM',reach,g.switch(enabled,0.,joint_reach))
    enabled=g.either(*active)
    room=g.either(g.boolean('NOT',enabled),g.compare(value('length'),
        g.math('ADD',.001,g.math('ADD',value('start_length'),value('end_length'))),'GREATER_THAN'))
    previous=lambda name,kind='FLOAT':g.sample(result,value(name,kind),g.math('MAXIMUM',0.,g.math('SUBTRACT',index,1.)),kind,'CURVE')
    equal=g.all(g.close(value('width'),previous('width'),1e-6),g.close(value('offset'),previous('offset'),1e-6))
    explicit=g.all(active[0],g.compare(previous('end_length'),0.,'GREATER_THAN'),
        g.compare(value('start_id','INT'),previous('end_id','INT'),kind='INT'),
        g.close(value('start_length'),previous('end_length'),1e-5),
        g.close(value('start_width'),previous('end_width'),1e-6),
        g.close(value('start_offset'),previous('end_offset'),1e-6))
    seam=g.either(g.compare(index,0,kind='INT'),g.either(equal,explicit))
    for name,field,kind in (
        ('valid',g.all(room,seam),'BOOLEAN'),('room',room,'BOOLEAN'),('taper',enabled,'BOOLEAN'),('reach',reach,'FLOAT'),
        ('first_bound',g.math('MAXIMUM',bounds[0][0],bounds[1][0]),'FLOAT'),
        ('second_bound',g.math('MAXIMUM',bounds[0][1],bounds[1][1]),'FLOAT')):
        result=g.store(result,'st_span_'+name,field,kind,'CURVE')
    return result


def _values(g, curves, at, t):
    """Return actual width/offset and transition ID at a member control rank."""
    from . import path_station_nodes
    selected,count,length,_valid=path_station_nodes._selected_curve(g,curves,at,'Bundle dimensions')
    rank=g.math('MULTIPLY',t,g.math('SUBTRACT',count,1.))
    segment=g.math('MINIMUM',g.math('SUBTRACT',count,2.),g.math('MAXIMUM',0.,g.math('FLOOR',rank)))
    def value(name,kind='FLOAT'):
        return g.sample(selected,g.named('st_span_'+name,kind),segment,kind)
    distance=g.math('SUBTRACT',g.math('MULTIPLY',path_station_nodes._factor(g,selected,count,t),length),value('prefix'))
    width,offset=value('width'),value('offset')
    adjusted_width,adjusted_offset=width,offset;identity=-1
    for side,d in (('start',distance),('end',g.math('SUBTRACT',value('length'),distance))):
        half=value(side+'_length');tid=value(side+'_id','INT')
        active=g.all(g.compare(tid,0,'GREATER_EQUAL','INT'),g.compare(half,0.,'GREATER_THAN'))
        u=g.math('MINIMUM',1.,g.math('MAXIMUM',0.,g.math('DIVIDE',d,g.math('MAXIMUM',half,1e-6))))
        smooth=g.math('MULTIPLY',g.math('POWER',u,3.),g.math('ADD',10.,
            g.math('MULTIPLY',u,g.math('ADD',-15.,g.math('MULTIPLY',6.,u)))))
        weight=g.switch(active,0.,g.math('SUBTRACT',1.,smooth))
        adjusted_width=g.math('ADD',adjusted_width,g.math('MULTIPLY',weight,g.math('SUBTRACT',value(side+'_width'),width)))
        adjusted_offset=g.math('ADD',adjusted_offset,g.math('MULTIPLY',weight,g.math('SUBTRACT',value(side+'_offset'),offset)))
        identity=g.switch(g.all(active,g.compare(d,half,'LESS_THAN')),identity,tid,'INT')
    active=g.sample(curves,g.named('st_sweep_variable_dimensions','BOOLEAN'),at,'BOOLEAN','CURVE')
    original_width=g.sample(curves,g.named('st_sweep_width','FLOAT'),at,'FLOAT','CURVE')
    original_offset=g.sample(curves,g.named('st_sweep_offset','FLOAT'),at,'FLOAT','CURVE')
    return (g.switch(active,original_width,adjusted_width),g.switch(active,original_offset,adjusted_offset),
            g.switch(active,-1,identity,'INT'))


def values(g, curves, at, t):
    """Share the dimensional field program across every boundary and face query."""
    import bpy
    from .path_surface_nodes import _Nodes
    name='Prochitecture Streets / Bundle Section dimensions v1'
    tree=bpy.data.node_groups.get(name)
    if tree is None:
        tree=bpy.data.node_groups.new(name,'GeometryNodeTree')
        for label,kind in (('Curves','NodeSocketGeometry'),('Path','NodeSocketInt'),('Rank','NodeSocketFloat')):
            tree.interface.new_socket(name=label,in_out='INPUT',socket_type=kind)
        for label,kind in (('Width','NodeSocketFloat'),('Offset','NodeSocketFloat'),('Transition','NodeSocketInt')):
            tree.interface.new_socket(name=label,in_out='OUTPUT',socket_type=kind)
        h=_Nodes(tree);inp=h.node('NodeGroupInput','Live member dimensions')
        out=h.node('NodeGroupOutput','Finite declared taper or unchanged Section dimensions')
        fields=_values(h,inp.outputs['Curves'],inp.outputs['Path'],inp.outputs['Rank'])
        for label,field in zip(('Width','Offset','Transition'),fields):h.set(field,out.inputs[label])
    node=g.node('GeometryNodeGroup','Shared live Bundle Section dimensions');node.node_tree=tree
    for label,value in zip(('Curves','Path','Rank'),(curves,at,t)):g.set(value,node.inputs[label])
    return tuple(node.outputs[label] for label in ('Width','Offset','Transition'))
